record.field:
for rec in records:
    result = quest.build(message=rec.csrd_name,session=session).invoke({"messages": [HumanMessage(content=rec.csrd_name)]})
    if result:
        answer = quest.get_last_ai_message_content(result)
        dicts = quest.extract_dicts(answer)
        if dicts:
            if str(dicts[0].get("relevant")).lower() == "false":
                record.write({'active': False})
            record.message_post( body=dicts[0].get("reason"), subtype_xmlid='mail.mt_note', message_type='comment')
